contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool flip) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        // record balances before the call
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General invariant: for any input, either the call reverted, or C's balance is zero
        // and this contract's balance is at least as large as before (it does not lose Ether).
        assert(reverted || (address(c).balance == 0 && address(this).balance >= beforeThis));
    }
    receive() external payable { }
}

